    function scheduleView(){const s=state();return '<section class="hsw-panel"><h2>Kế hoạch học của bạn</h2><form data-hsw-plan><label>Thời lượng dự kiến mỗi ngày<input name="minutes" type="number" min="10" max="120" value="'+s.preferences.dailyMinutes+'"></label><label>Mục tiêu trong tuần<input name="goal" maxlength="240" value="'+esc(prefs().goal || '')+'" placeholder="Ví dụ: hiểu phân số và sửa các lỗi về mẫu số"></label><button type="submit">Lưu kế hoạch</button></form><p>'+esc(prefs().goal || 'Chọn mục tiêu nhỏ, dành thời gian làm bài và ôn sau một khoảng nghỉ.')+' · '+s.preferences.dailyMinutes+' phút/ngày là mục tiêu do bạn chọn.</p></section>';}
    function subjects() {
      const s=state(),p=pack(),subjects=p.grade.subjects,active=subjects.find(x=>x.id===s.activeSubjectId)||subjects[0],lessons=visibleLessons(p).filter(l=>l.subjectId===active.id),raw=content.peekGrade(s.profile.grade),mapped=raw?.subjects?.find(x=>x.id===active.id);
      return header('LỚP '+s.profile.grade,'Môn học và chương trình','Mỗi bài có mục tiêu, hướng dẫn, hoạt động và phần tự làm. Môn lựa chọn vẫn có thể đọc tự do.')+controls()+'<div class="hsw-subject-layout"><nav class="hsw-subject-nav" aria-label="Các môn lớp '+s.profile.grade+'">'+subjects.map(x=>'<button type="button" data-school-subject="'+esc(x.id)+'" '+(x.id===active.id?'aria-current="page"':'')+'><span>'+esc(x.icon)+'</span><b>'+esc(x.name)+'</b><small>'+p.lessons.filter(l=>l.subjectId===x.id).length+' bài · '+(x.optional?'tự chọn':'chương trình')+'</small></button>').join('')+'</nav><section class="hsw-subject-content"><div class="hsw-subject-title"><small>'+esc(p.grade.stage)+'</small><h2>'+esc(active.name)+'</h2><p>'+esc(mapped?.description || 'Theo dõi chương, bài và nguồn đối chiếu; độ phủ chỉ xác nhận khi đã đối chiếu đầy đủ yêu cầu cần đạt.')+'</p></div>'+(mapped?.chapters?.length?'<details class="hsw-panel"><summary>Chương/chủ đề và yêu cầu cần đạt</summary>'+mapped.chapters.map(ch=>'<article class="hsw-chapter"><h3>'+esc(ch.title)+'</h3><small>Học kỳ '+esc(ch.semester || '—')+'</small><p>'+esc((ch.outcomeIds || []).map(id=>raw.outcomes?.find(o=>o.id===id)?.text || id).join(' · '))+'</p></article>').join('')+'</details>':'')+'<div class="hsw-chapter-groups">'+([...new Set(lessons.map(l=>l.chapterId))].map(id=>{const chapter=mapped?.chapters?.find(c=>c.id===id),items=lessons.filter(l=>l.chapterId===id);return '<section class="hsw-chapter-group"><header><h3>'+esc(chapter?.title||items[0].title)+'</h3><span>'+items.length+' bài</span></header><div class="hsw-lesson-grid">'+items.map(lessonCard).join('')+'</div></section>';}).join('')||empty(prefs().previewContent?'Chưa có bài biên soạn cho phần này':undefined,mapped?.status==='needs-local-source'?'Chọn đúng địa phương và đối chiếu tài liệu địa phương trước khi công bố.':undefined))+'</div></section></div>';
    }
    function paragraphs(text){return String(text || '').split(/\n\s*\n/).filter(Boolean).map(t=>'<p>'+esc(t).replace(/\n/g,'<br>')+'</p>').join('');}
    function formQuestion(q,lessonId,idx=0){const result=resultMap.get(q.id),storedDraft=prefs().practiceDrafts?.[q.id],draft=storedDraft?.submitted?null:storedDraft,disabled=!!result;return '<form class="hhs-question hsw-question" data-hsw-question="'+esc(q.id)+'" data-lesson-id="'+esc(lessonId)+'" data-started-at="'+Date.now()+'" data-help-level="'+Number(draft?.helpLevel||0)+'"><small>Câu '+(idx+1)+' · '+esc(q.cognitiveLevel || 'Tự luyện')+'</small><h3>'+esc(q.prompt)+'</h3>'+questionFields(q,result?.answer??draft?.value,disabled)+(q.rubric?.length?'<details><summary>Tiêu chí đối chiếu</summary><ul>'+q.rubric.map(r=>'<li>'+esc(typeof r==='string'?r:r.description||r.criterion||r.title)+'</li>').join('')+'</ul></details>':'')+'<div class="hsw-question-actions"><button type="submit" '+(disabled?'disabled':'')+'>Ghi nhận bài làm</button><button type="button" data-hsw-hint="'+esc(q.id)+'">Gợi ý</button></div><output data-hsw-feedback="'+esc(q.id)+'">'+(result?feedback(result):'')+'</output></form>';}
    function feedback(result){const r=result.result;return '<strong>'+(r.gradingStatus==='pending-review'?'Đã lưu để đối chiếu rubric':r.correct?'Đúng theo đáp án':'Cần xem lại')+'</strong><p>'+esc(r.explanation || 'Đối chiếu dữ kiện và thử lại một câu khác.')+'</p><small>'+(r.gradingStatus==='pending-review'?'Chưa gửi giáo viên; chưa có điểm chuyên môn.':result.preview?'Lượt luyện thử trên bản biên soạn; không xác nhận thành thạo.':'Lượt làm đã lưu theo kỹ năng.')+'</small>';}
    function progress() {
      const s=state(),lessons=pack().lessons,byId=new Map(lessons.map(l=>[l.lessonId,l]));
      const names=new Map(lessons.flatMap(l=>l.questions.map(q=>[q.skillId,l.title])));
      const due=s.reviews.filter(r=>Date.parse(r.dueAt)<=Date.now()&&byId.has(r.lessonId));
      const mistakes=s.mistakes.filter(row=>byId.has(row.lessonId));
      const verified=Object.values(s.mastery).filter(m=>m.evidenceScope==='reviewed-content'),provisional=Object.values(s.mastery).filter(m=>m.evidenceScope!=='reviewed-content');
      const overview=[[s.attempts.length,'lượt làm đã lưu'],[verified.filter(m=>m.state==='mastered').length,'kỹ năng đạt tiêu chí bằng chứng'],[provisional.length,'kỹ năng đang luyện thử'],[due.length,'thẻ đến hạn trong nội dung đang mở']];
      const summary='<section class="hsw-stat-row">'+overview.map(([value,label])=>'<article><b>'+value+'</b><span>'+esc(label)+'</span></article>').join('')+'</section>';
      const cards=mistakes.map(m=>'<article class="hsw-flashcard"><p>'+esc(byId.get(m.lessonId).title)+'</p><h3>'+esc(m.prompt)+'</h3><span>Trước khi lật, thử tự trả lời bằng lời của bạn.</span><details><summary>Lật thẻ · xem cách đối chiếu</summary><p>Đáp án theo bài: '+esc(m.expected)+'</p><p>'+esc(m.explanation)+'</p><small>Lần trước bạn trả lời: '+esc(m.userAnswer)+'</small></details><div><button type="button" data-school-practice-lesson="'+esc(m.lessonId)+'">Làm lại bài liên quan</button><button type="button" data-school-open-lesson="'+esc(m.lessonId)+'">Đọc lại kiến thức</button></div></article>').join('');
      const dueList=due.map(r=>'<article><h3>'+esc(byId.get(r.lessonId).title)+'</h3><p>'+esc(r.reason)+'</p><button type="button" data-school-practice-lesson="'+esc(r.lessonId)+'">Ôn bằng bài tự làm</button></article>').join('');
      const skills=Object.entries(s.mastery).filter(([id])=>names.has(id)).map(([id,m])=>'<article><h3>'+esc(names.get(id))+'</h3><p>'+esc(m.evidenceScope==='reviewed-content'?'Bằng chứng từ nội dung đã duyệt':'Luyện thử; chưa xác nhận thành thạo')+'</p><dl><dt>Lượt làm / độ chính xác theo đáp án</dt><dd>'+Number(m.attempts||0)+' / '+Number(m.accuracy||0)+'%</dd><dt>Họ câu có bằng chứng đủ điều kiện</dt><dd>'+Number(m.distinctFamilies||0)+'</dd><dt>Họ câu được làm lại cách ngày</dt><dd>'+Number(m.delayedFamilies||0)+'</dd></dl></article>').join('');
      return header('ÔN TẬP VÀ BẰNG CHỨNG','Tiến độ, thẻ ôn và sổ lỗi','Lật thẻ giúp xem lại hướng dẫn; chỉ lượt tự làm phù hợp mới tạo bằng chứng học tập.','<button type="button" data-school-export="csv">Xuất CSV kỹ năng</button>')+summary+'<section class="hsw-panel"><h2>Ôn đến hạn</h2>'+(dueList||'<p>Chưa có thẻ đến hạn trong phạm vi nội dung đang hiển thị.</p>')+'</section><section class="hsw-panel"><h2>Thẻ ôn từ lỗi đã làm</h2><div class="hsw-lesson-grid">'+(cards||'<p>Chưa có lỗi trong nội dung đang mở. Làm một bài luyện để nhận phản hồi và lưu sổ lỗi.</p>')+'</div></section><section class="hsw-panel"><h2>Bằng chứng theo bài</h2><div class="hsw-lesson-grid">'+(skills||'<p>Chưa có lượt làm trong phạm vi này.</p>')+'</div></section><p>Toàn bộ lịch sử vẫn giữ trong dữ liệu của hồ sơ. Tắt xem trước sẽ ẩn câu và bài chưa thẩm định khỏi thẻ ôn.</p>';
    }
    function lesson() {
      const s=state(),lessons=pack().lessons,l=lessons.find(l=>l.lessonId===s.activeLessonId)||lessons[0];if(!l)return empty();
      const steps=sections(l),step=Math.min(steps.length-1,Number(s.progress[l.lessonId]?.step)||0),current=steps[step],qs=l.questions || [],chosen=current.id==='quickcheck'?(qs.filter(q=>q.phase==='check').length?qs.filter(q=>q.phase==='check'):qs.slice(-2)):current.id==='practice'?(qs.filter(q=>q.phase==='practice').length?qs.filter(q=>q.phase==='practice'):qs.slice(0,Math.max(1,qs.length-2))):[];
      const note=prefs().notes[l.lessonId]?.text || '',evidence=C.lessonEvidence?.(s,l.lessonId),wide=!root.matchMedia?.('(max-width:760px)').matches;
      return '<section class="hsw-lesson"><header class="hsw-lesson-top"><button type="button" data-school-view="subjects">← Môn học</button><div><small>'+esc(base.subjectBy(l.subjectId)?.name)+' · Lớp '+s.profile.grade+'</small><h1>'+esc(l.title)+'</h1><p>'+esc(l.outcome)+'</p></div><button type="button" data-hsw-bookmark="'+esc(l.lessonId)+'" aria-pressed="'+prefs().bookmarks.includes(l.lessonId)+'">'+(prefs().bookmarks.includes(l.lessonId)?'Đã lưu':'Lưu bài')+'</button></header><div class="hsw-lesson-layout"><details class="hsw-outline-box" '+(wide?'open':'')+'><summary>Mục lục bài học <span>Bước '+(step+1)+'/'+steps.length+'</span></summary><nav class="hsw-outline" aria-label="Các bước của bài">'+steps.map((st,i)=>'<button type="button" data-lesson-step="'+i+'" '+(i===step?'aria-current="step"':'')+'><i>'+(i+1)+'</i>'+esc(st.label)+'</button>').join('')+'</nav></details><article class="hsw-reading"><small>Bước '+(step+1)+' / '+steps.length+'</small><h2>'+esc(current.label)+'</h2>'+paragraphs(current.body)+(current.id==='core'?diagramMarkup(l.diagram):'')+((current.id==='goal'||current.id==='next')&&l.prerequisites?.length?'<section class="hsw-prerequisites"><h3>Kiến thức nên ôn trước</h3>'+l.prerequisites.map(id=>{const prior=lessons.find(x=>x.lessonId===id)||content.manifest.grades.flatMap(g=>g.lessons).find(x=>x.id===id);return prior?'<button type="button" data-school-open-lesson="'+esc(id)+'">'+esc(prior.title)+'</button>':'';}).join('')+'</section>':'')+(current.id==='guided'&&l.workedExample?'<section class="hsw-example"><h3>'+esc(l.workedExample.prompt)+'</h3><ol>'+l.workedExample.method.map(m=>'<li>'+esc(m)+'</li>').join('')+'</ol><details><summary>Đối chiếu kết quả ví dụ</summary><p>'+esc(l.workedExample.answer)+'</p></details></section>':'')+(current.id==='interactive'?listening(l)+lab(l):'')+chosen.map((q,i)=>formQuestion(q,l.lessonId,i)).join('')+(current.id==='summary'?'<ul>'+l.commonMistakes.map(m=>'<li>'+esc(m)+'</li>').join('')+'</ul>':'')+'<footer class="hsw-reading-nav"><button type="button" data-lesson-prev '+(!step?'disabled':'')+'>← Quay lại</button><span>Điều hướng chỉ ghi nhận đã xem</span><button type="button" class="hsw-primary" data-lesson-next>'+(step===steps.length-1?'Kết thúc lượt đọc':'Bước tiếp →')+'</button></footer></article><details class="hsw-note-panel" '+(wide||note?'open':'')+'><summary>Ghi chú của bạn</summary><div><label for="hsw-lesson-note">Viết điều đã hiểu và câu hỏi còn vướng</label><textarea id="hsw-lesson-note" data-hsw-note="'+esc(l.lessonId)+'" maxlength="6000" rows="8">'+esc(note)+'</textarea><output data-hsw-note-status>Ghi chú lưu trên thiết bị theo hồ sơ.</output><p>'+esc(evidence?.label || 'Làm phần tự luyện để lưu bằng chứng; đọc hết bài chưa đồng nghĩa thành thạo.')+'</p><details><summary>Nguồn và trạng thái nội dung</summary><p>'+esc(base.canPublish(l)?'Đủ điều kiện xuất bản':draftLabel)+'</p><a href="'+esc(l.source?.sourceUrl || '#')+'" target="_blank" rel="noopener noreferrer">'+esc(l.source?.sourceTitle || 'Nguồn đang đối chiếu')+'</a>'+(l.additionalDraftReferences||[]).filter(r=>/^https?:\/\//.test(r.url||'')).map(r=>'<p><a href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">'+esc(r.title)+'</a><br>'+esc(r.edition||'')+'<br>'+esc(r.checkedScope||'')+'</p>').join('')+'</details></div></details></div></section>';
    }
    function listening(l){const audio=l.listening;if(!audio?.transcript)return '';return '<section class="hsw-lab"><h3>Nghe và đọc đối chiếu</h3><p>Giọng đọc máy của trình duyệt cho ngữ liệu nguyên bản; không phải audio của sách giáo khoa và không chấm phát âm.</p><div class="hsw-question-actions"><button type="button" data-hsw-speak="'+esc(l.lessonId)+'">Nghe đoạn mẫu</button><button type="button" data-hsw-speak-stop>Dừng đọc</button><label>Tốc độ<select data-hsw-speech-rate><option value="0.75">Chậm</option><option value="1" selected>Bình thường</option></select></label></div><output data-hsw-speech-status role="status">Chỉ phát khi bạn chọn. Thiết bị thiếu giọng phù hợp vẫn đọc được bản chữ.</output><details><summary>Bản chữ đối chiếu</summary><p lang="'+esc(audio.language || 'en-US')+'">'+esc(audio.transcript)+'</p></details></section>';}
    function lab(l){
      const title=(l.title+' '+l.outcome).toLowerCase(),grade=state().profile.grade;
      if(l.diagram?.type==='hundred-grid')return '<section class="hsw-lab"><h3>Một toàn thể, một trăm ô</h3><form data-hsw-lab="percent"><label>Số ô được tô (0–100)<input name="a" type="number" min="0" max="100" value="'+l.diagram.selected+'"></label><input name="b" type="hidden" value="100"><button type="submit">Biểu diễn phần trăm</button></form><output data-hsw-lab-output>'+diagramMarkup(l.diagram)+'</output><p>Mỗi ô bằng 1% của cùng một toàn thể; mô hình chỉ xét 0–100%.</p></section>';
      if(l.subjectId==='math'&&grade<=2)return '<section class="hsw-lab"><h3>Ghép và đếm nhóm</h3><form data-hsw-lab="count"><label>Nhóm thứ nhất<input name="a" type="number" min="0" max="10" value="3"></label><label>Nhóm thứ hai<input name="b" type="number" min="0" max="10" value="4"></label><button type="submit">Ghép hai nhóm</button></form><output data-hsw-lab-output>Đặt số lượng rồi quan sát từng nhóm.</output></section>';
      if(l.subjectId==='math'&&/phân số|tử số|mẫu số/.test(title))return '<section class="hsw-lab"><h3>Phần bằng nhau của một toàn thể</h3><form data-hsw-lab="fraction"><label>Số phần đã chọn<input name="a" type="number" min="0" max="12" value="3"></label><label>Tổng số phần bằng nhau<input name="b" type="number" min="1" max="12" value="4"></label><button type="submit">Biểu diễn phân số</button></form><output data-hsw-lab-output>Các phần phải bằng nhau; tử số không vượt mẫu trong mô hình một toàn thể này.</output></section>';
      if(/áp suất/.test(title))return '<section class="hsw-lab"><h3>Áp suất: giữ lực, thay diện tích</h3><form data-hsw-lab="pressure"><label>Lực vuông góc F (N)<input name="a" type="number" min="1" max="1000" value="20"></label><label>Diện tích S (m²)<input name="b" type="number" min="0.001" max="10" step="0.001" value="0.1"></label><button type="submit">Tính p = F / S</button></form><output data-hsw-lab-output>Mô hình lý tưởng: lực phân bố đều trên mặt phẳng; chưa xét biến dạng.</output></section>';
      return '<section class="hsw-activity"><h3>Tự giải thích và kiểm chứng</h3><p>'+esc(l.mission?.prompt || 'Dùng ví dụ trong bài: nêu dữ kiện, giải thích từng bước và tự kiểm tra kết luận. Ghi lại cách làm của bạn ở phần ghi chú.')+'</p></section>';
    }
    function bank(){return visibleLessons().filter(l=>l.subjectId===state().activeSubjectId).flatMap(l=>(l.questions||[]).map(q=>({...q,lessonId:l.lessonId,gradeId:l.gradeId,subjectId:l.subjectId,outcomeId:q.outcomeId||l.outcomeIds?.[0]||q.skillId,familyId:q.familyId||q.id,contentVersion:q.contentVersion||1,contentStatus:l.contentStatus})));}
    function practice(){const s=state(),all=bank(),weak=new Set(s.mistakes.map(m=>m.questionId)),due=new Set(s.reviews.filter(r=>Date.parse(r.dueAt)<=Date.now()).map(r=>r.skillId));if(!cachedPractice){const sorted=all.slice().sort((a,b)=>Number(b.lessonId===s.activeLessonId)-Number(a.lessonId===s.activeLessonId)||Number(weak.has(b.id))-Number(weak.has(a.id))||Number(due.has(b.skillId))-Number(due.has(a.skillId)));cachedPractice=sorted.slice(0,6);}return header('LUYỆN THEO KỸ NĂNG','Tự làm, hiểu lỗi, thử lại','Chọn môn ở trang Môn học. Câu mở được lưu để đối chiếu; điểm xác định chỉ dành cho dạng có đáp án kiểm chứng.','<button type="button" data-hsw-new-practice>Chọn bộ câu khác</button>')+controls()+'<p class="hsw-context">'+esc(base.subjectBy(s.activeSubjectId)?.name || s.activeSubjectId)+' · Lớp '+s.profile.grade+'</p><div class="hhs-practice-grid">'+(cachedPractice.map((q,i)=>formQuestion(q,q.lessonId,i)).join('')||empty())+'</div>';}
    function exam(){
      const s=state(),p=prefs(),session=p.examSessions[p.activeExamId],all=bank(),families=new Set(all.map(q=>q.familyId||q.id)).size;
      if(session&&!p.previewContent&&session.blueprint?.contentStatus==='draft')return empty('Phiên này dùng bản biên soạn','Phiên đã lưu được giữ. Bật xem trước nội dung để tiếp tục hoặc đọc lại kết quả.');
      if(!session)return header('ĐÁNH GIÁ TRONG ỨNG DỤNG','Luyện đề và thi thử','Đề tự biên soạn theo ngân hàng đang hiển thị. Đây chưa phải đề chính thức hoặc bộ đề đã hiệu chuẩn.')+'<section class="hsw-panel"><h2>'+esc(base.subjectBy(s.activeSubjectId)?.name || s.activeSubjectId)+' · Lớp '+s.profile.grade+'</h2><form data-hsw-exam-create><label>Cách làm<select name="mode"><option value="practice">Luyện đề · có thể tạm dừng và xem chữa câu</option><option value="mock">Thi thử · đồng hồ chạy liên tục</option></select></label><label>Số câu<select name="count">'+[4,6,8,10].filter(n=>n<=families).map(n=>'<option value="'+n+'">'+n+' câu</option>').join('')+'</select></label><label>Thời gian (phút)<input name="minutes" type="number" min="2" max="180" value="15"></label><button type="submit" '+(families<4?'disabled':'')+'>Chuẩn bị đề</button></form><p>Ngân hàng hiện có '+all.length+' câu trong phạm vi đang chọn. Thi thử vẫn tính giờ khi đổi tab, rời trang hoặc tải lại; bài tự luận giữ trạng thái cần đối chiếu.</p></section>'+examHistory();
      const view=A.view(session,{now:Date.now()}),questions=view.questions || session.questions,index=Math.max(0,Math.min(questions.length-1,view.questionIndex??session.questionIndex??0)),q=questions[index],submitted=session.status==='submitted',answer=session.answers?.[q.id]?.value??session.answers?.[q.id];
      return header(session.mode==='mock'?'THI THỬ · ĐỀ CỐ ĐỊNH':'LUYỆN ĐỀ',session.title || session.blueprint?.title || 'Bài kiểm tra của bạn',submitted?'Bài đã nộp. Đối chiếu từng câu và chọn bài học bù.':'Câu và thời hạn được giữ nguyên khi tải lại.','<button type="button" data-hsw-exam-close>Về danh sách đề</button>')+'<div class="hsw-exam-bar"><strong data-hsw-exam-clock>'+clockText(A.remainingMs(session,Date.now()))+'</strong><span>'+(submitted?'Đã nộp':session.status==='paused'?'Đang tạm dừng':'Đang làm')+'</span>'+(!submitted&&session.mode==='practice'?'<button type="button" data-hsw-exam-pause>'+(session.status==='paused'?'Tiếp tục':'Tạm dừng')+'</button>':'')+'<button type="button" data-hsw-exam-finish '+(submitted?'disabled':'')+'>Nộp bài</button></div>'+ (submitted?examResult(session):'')+'<div class="hsw-exam-layout"><nav class="hsw-question-nav" aria-label="Các câu trong đề">'+questions.map((item,i)=>'<button type="button" data-hsw-exam-nav="'+i+'" '+(i===index?'aria-current="step"':'')+' aria-label="Câu '+(i+1)+(session.flagged?.includes(item.id)?' đã đánh dấu':'')+'">'+(i+1)+(session.flagged?.includes(item.id)?' ⚑':'')+'</button>').join('')+'</nav><form class="hhs-question" data-hsw-exam-answer="'+esc(q.id)+'"><h2>Câu '+(index+1)+'</h2><h3>'+esc(q.prompt)+'</h3>'+questionFields(q,answer,submitted||session.status==='paused')+'<div class="hsw-question-actions"><button type="submit" '+(submitted||session.status==='paused'?'disabled':'')+'>Lưu câu trả lời</button><button type="button" data-hsw-exam-flag="'+esc(q.id)+'" '+(submitted?'disabled':'')+'>⚑ Xem lại</button></div><output data-hsw-answer-status></output>'+(submitted?examReview(session,q):'')+'</form></div>';
    }
    function clockText(ms){const seconds=Math.ceil(Math.max(0,ms)/1000);return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
    function examResult(session){
      const r=session.result || {},rows=r.byOutcome || [],labels=new Map(session.questions.flatMap(q=>(q.outcomeIds || []).map(id=>[id,pack().lessons.find(l=>l.lessonId===q.lessonId)?.title || id])));
      return '<section class="hsw-result"><h2>Kết quả luyện tập</h2><p>'+esc(r.percent===null?'Có phần cần nhận xét; chưa có tổng điểm xác nhận.':Number.isFinite(r.percent)?'Điểm đáp án xác định: '+r.percent.toFixed(1)+'%':'Đã lưu kết quả và trạng thái từng câu.')+'</p><p>Đề tự biên soạn; không quy đổi thành điểm thi chính thức. '+(session.blueprint.contentStatus==='draft'?'Nội dung trong đề đang chờ thẩm định.':'')+'</p><p>Thời gian theo đồng hồ phiên: '+Math.ceil((r.elapsedMs || 0)/1000)+' giây; không tự xác nhận thời gian tập trung.</p><div class="hsw-outcome-results">'+rows.map(row=>'<article><h3>'+esc(labels.get(row.outcomeId) || row.outcomeId)+'</h3><p>'+Number(row.earnedPoints || 0).toFixed(2)+' / '+Number(row.maxPoints || 0).toFixed(2)+' điểm xác định · '+Number(row.pending || 0)+' câu cần đối chiếu rubric</p><p>'+Number(row.needsReview?.length || 0)+' câu cần xem lại. Chọn số câu bên dưới để đọc hướng dẫn và mở bài liên quan.</p></article>').join('')+'</div></section>';
    }
    function examReview(session,q){try{const r=A.review(session,q.id,{gradeQuestion:C.gradeQuestion});return '<section class="hsw-review"><h3>Chữa câu</h3><p>'+esc(r.grade?.explanation || r.explanation || q.explanation || 'Đối chiếu rubric của câu.')+'</p><button type="button" data-school-open-lesson="'+esc(q.lessonId)+'">Học lại bài liên quan</button></section>';}catch{return '';}}
    function examHistory(){const sessions=Object.values(prefs().examSessions);return '<section class="hsw-panel"><h2>Các phiên đã lưu trên thiết bị</h2>'+sessions.map(session=>'<button type="button" data-hsw-exam-open="'+esc(session.id)+'">'+esc(session.title || session.blueprint?.title || 'Phiên luyện')+' · '+esc(session.status)+'</button>').join('')+(sessions.length?'':'<p>Chưa có phiên kiểm tra.</p>')+'</section>';}
    function library(){const s=state(),raw=content.peekGrade(s.profile.grade),legacy=sourcePack(s.profile.grade),lessons=raw?.lessons || [],published=lessons.filter(l=>base.canPublish(l));return header('NGUỒN VÀ ĐỘ PHỦ','Thư viện học liệu','Phân biệt cấu trúc chương trình, bài biên soạn và nội dung đã qua thẩm định.')+'<section class="hsw-stat-row"><article><b>'+legacy.grade.subjects.length+'</b><span>môn/hoạt động trong catalog lớp</span></article><article><b>'+(raw?.outcomes?.length || 0)+'</b><span>mục tiêu nội bộ đã liên kết</span></article><article><b>'+lessons.length+'</b><span>bản ghi bài biên soạn</span></article><article><b>'+published.length+'</b><span>bài đủ điều kiện xuất bản</span></article></section><details class="hsw-panel"><summary>Nguồn đối chiếu và giới hạn nội dung</summary><p>Số yêu cầu ghi vào ma trận không tự chứng minh đã trích đủ chương trình. Bản nháp không được tính là học liệu đã được giáo viên/Bộ phê duyệt. Nguồn chương trình là tài liệu đối chiếu; bài giảng được biên soạn nguyên bản.</p>'+[...(raw?.sources || []),...legacy.sources].map(src=>'<p>'+(src.url||src.sourceUrl?'<a href="'+esc(src.url || src.sourceUrl)+'" target="_blank" rel="noopener noreferrer">'+esc(src.title || src.sourceTitle)+'</a>':esc(src.title || src.sourceTitle))+' · '+esc(src.licenseCode || 'Tham chiếu')+(src.gap?'<br><small>'+esc(src.gap)+'</small>':'')+'</p>').join('')+'<button type="button" data-hsw-export-coverage>Xuất ma trận của lớp</button></details><section class="hsw-panel"><h2>Bài đã lưu</h2><div class="hsw-lesson-grid">'+prefs().bookmarks.map(id=>pack().lessons.find(l=>l.lessonId===id)).filter(Boolean).map(lessonCard).join('')+'</div></section><section class="hsw-panel"><h2>Khôi phục dữ liệu</h2><details class="hsw-cloud-pending"><summary>Phiên đồng bộ chưa hoàn tất</summary><p>Bạn có thể tiếp tục gửi lại cùng dữ liệu. Hủy phiên chỉ xóa phần đang gửi dở trên máy chủ; bản đã công bố và dữ liệu thiết bị vẫn được giữ.</p><button type="button" data-hsw-cloud-pending>Xem phiên đang chờ</button><div data-hsw-cloud-list role="status"></div></details><p>Backup chứa bài làm và ghi chú cá nhân. Chỉ nhập bản của đúng tài khoản và hồ sơ.</p><button type="button" data-school-export="json">Xuất backup</button><form data-hsw-import><label>File backup HH School<input name="backup" type="file" accept="application/json,.json" required></label><button type="submit">Nhập backup</button></form></section>';}
    function assignmentView(){const s=state();return '<section class="hsw-panel"><h2>Bài được giao</h2>'+s.assignments.map(a=>{const id=String(a.id || a._id || ''),submission=s.submissions.find(x=>String(x.assignmentId)===id);return '<article class="hsw-assignment"><h3>'+esc(a.title)+'</h3><p>Hạn nộp: '+esc(a.dueAt?new Date(a.dueAt).toLocaleString('vi-VN'):'—')+'</p>'+(a.lessonIds || []).map(l=>'<button type="button" data-school-open-lesson="'+esc(l)+'">Mở bài liên quan</button>').join('')+'<form data-hsw-assignment="'+esc(id)+'"><label>Bài làm / bản sửa<textarea name="answer" rows="4" maxlength="12000">'+esc(submission?.answer || '')+'</textarea></label><button type="submit">Nộp bài trên máy chủ</button><output data-hsw-assignment-save></output></form>'+(submission?'<p>'+esc(submission.status)+' · '+esc(submission.feedback || 'Chưa có nhận xét từ giáo viên.')+'</p>':'')+(submission?.serverRecord&&Number(submission.remoteRevision)>Number(submission.answerRevision||0)?'<details><summary>Có bản mới hơn trên máy chủ; bản nháp của bạn vẫn được giữ</summary><pre class="hsw-student-answer">'+esc(submission.serverRecord.answer)+'</pre><p>'+esc(submission.serverRecord.feedback || '')+'</p><button type="button" data-hsw-assignment-server="'+esc(id)+'">Dùng bản máy chủ thay bản nháp đang hiển thị</button></details>':'')+'</article>';}).join('')+(s.assignments.length?'':'<p>Bài giao sẽ xuất hiện sau khi tham gia lớp và tải được dữ liệu từ máy chủ.</p>')+'</section>';}
    let teacherClass='', teacherRequest=0, teacherData={assignments:[],submissions:[],loading:false,error:''}, assignmentTimer=0, writeAssignment=null;
    let editorial={loaded:false,loading:false,error:'',versions:[],queue:[]},editorialRequest=0;
    async function loadEditorial(){
      const request=++editorialRequest;editorial={...editorial,loading:true,error:''};
      try{
        const [versions,queue]=await Promise.all([instance.sync.content(),instance.sync.reviewQueue()]);
        if(disposed||request!==editorialRequest)return;
        editorial={loaded:true,loading:false,error:'',versions:versions.items || [],queue:queue.items || []};
      }catch(error){if(disposed||request!==editorialRequest)return;editorial={...editorial,loaded:true,loading:false,error:error.message};}
      render();
    }
    function admin(){
      if(!C.can(state().role,'review-content'))return header('QUYỀN TRUY CẬP','Chưa có quyền biên tập','Tài khoản cần được phân quyền kiểm duyệt ở máy chủ.');
      if(!editorial.loaded&&!editorial.loading)void loadEditorial();
      const lessons=pack().lessons;
      return header('BIÊN TẬP VÀ KIỂM CHỨNG','Học liệu và đề xuất chỉnh sửa','Lưu phiên bản nháp và ghi nhận đề xuất trên máy chủ. Không tự đổi bản biên soạn thành nội dung đã thẩm định.','<button type="button" data-hsw-editor-refresh>Làm mới dữ liệu máy chủ</button>')+(editorial.loading?'<output role="status">Đang tải nội dung và hàng đề xuất…</output>':'')+(editorial.error?'<output role="status" class="hsw-storage-error">'+esc(editorial.error)+'</output>':'')+'<section class="hsw-panel"><h2>Soạn bản nháp</h2><form data-hsw-editor-draft><label>Lấy nội dung đang xem trước<select data-hsw-editor-source><option value="">Nhập bản biên soạn mới</option>'+lessons.map(l=>'<option value="'+esc(l.lessonId)+'">'+esc(l.title)+'</option>').join('')+'</select></label><label>ID nội dung<input name="contentId" required maxlength="100" pattern="[a-zA-Z0-9._-]+"></label><label>Tiêu đề<input name="title" required maxlength="160"></label><label>Nội dung JSON (tối đa 120 KB)<textarea name="payload" rows="12" spellcheck="false" required>{"steps":[],"questions":[]}</textarea></label><button type="submit">Lưu phiên bản nháp trên máy chủ</button></form><p>Đề xuất và bản nháp chưa thay đổi các gói đã xuất bản. Việc thẩm định chuyên môn và phát hành phiên bản nội dung cần bằng chứng riêng.</p></section><section class="hsw-panel"><h2>Đề xuất sửa bài</h2><form data-hsw-editor-proposal><label>ID bài học<input name="lessonId" required maxlength="100"></label><label>Lỗi, nguồn đối chiếu và đề xuất<textarea name="note" maxlength="1000" rows="4" required></textarea></label><button type="submit">Gửi đề xuất đến máy chủ</button></form></section><section class="hsw-panel"><h2>'+editorial.versions.length+' phiên bản tải về</h2>'+editorial.versions.map(v=>'<article><h3>'+esc(v.title)+'</h3><p>'+esc(v.contentId)+' · phiên bản '+Number(v.version||0)+' · '+esc(v.status)+'</p><details><summary>Đọc nội dung và checksum</summary><code>'+esc(v.checksum)+'</code><pre class="hsw-student-answer">'+esc(JSON.stringify(v.payload,null,2))+'</pre></details></article>').join('')+'</section><section class="hsw-panel"><h2>'+editorial.queue.length+' đề xuất đang chờ</h2>'+editorial.queue.map(row=>'<article><h3>'+esc(row.lessonId)+'</h3><p>'+esc(row.note)+'</p><small>'+esc(row.status)+'</small></article>').join('')+'</section>';
    }
    const entryId=entry=>String(entry.id || entry._id || '');
    async function loadTeacherClass(classId){
      const request=++teacherRequest;teacherClass=classId;teacherData={assignments:[],submissions:[],loading:true,error:''};render();
      try{
        const query='classId='+encodeURIComponent(classId),[assignments,submissions]=await Promise.all([instance.sync.request('/assignments?'+query),instance.sync.submissions(query)]);
        if(disposed||request!==teacherRequest)return;
        teacherData={assignments:assignments.items || [],submissions:submissions.items || [],loading:false,error:''};render();
      }catch(error){if(disposed||request!==teacherRequest)return;teacherData={assignments:[],submissions:[],loading:false,error:error.message};render();}
    }
    function teacher(){
      const s=state();if(!C.can(s.role,'create-class')&&!C.can(s.role,'platform-admin'))return header('PHÂN QUYỀN','Khu vực giáo viên','Tài khoản hiện tại chưa có quyền quản lý lớp hoặc xem bài nộp.');
      const classes=s.classes,validClasses=classes.filter(c=>/^[a-f0-9]{24}$/i.test(entryId(c))),selected=validClasses.find(c=>entryId(c)===teacherClass)||validClasses[0];
      if(selected&&!teacherClass)void Promise.resolve().then(()=>{if(!disposed)void loadTeacherClass(entryId(selected));});
      return header('GIÁO VIÊN','Giao bài và phản hồi','Lớp, bài nộp và điểm nhận xét được kiểm tra quyền trên máy chủ.','<button type="button" data-teacher-create-class>Tạo lớp</button>')+'<section class="hsw-panel"><h2>Lớp của bạn</h2>'+classes.map(c=>'<article class="hsw-assignment"><h3>'+esc(c.name)+'</h3><p>Lớp '+esc(c.grade)+' · '+esc(c.syncStatus || 'Dữ liệu máy chủ')+'</p><button type="button" data-class-invite="'+esc(entryId(c))+'">Đổi mã mời</button> <button type="button" data-class-disable="'+esc(entryId(c))+'">Tắt mã</button></article>').join('')+(classes.length?'':'<p>Tạo lớp để giao bài. Lớp chỉ lưu trên thiết bị chưa có mã tham gia hợp lệ.</p>')+'</section><section class="hsw-panel"><h2>Chọn lớp đang quản lý</h2><label>Lớp đã đồng bộ<select data-hsw-teacher-class><option value="">Chọn lớp</option>'+validClasses.map(c=>'<option value="'+esc(entryId(c))+'" '+(entryId(c)===teacherClass?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label>'+(teacherData.loading?'<p role="status">Đang tải bài giao và bài nộp…</p>':teacherData.error?'<p role="status">'+esc(teacherData.error)+'</p>':'')+'<button type="button" data-hsw-teacher-refresh '+(!teacherClass?'disabled':'')+'>Tải lại dữ liệu lớp</button></section>'+(selected?'<section class="hsw-panel"><h2>Giao bài cho '+esc(selected.name)+'</h2><form data-hsw-teacher-assign><label>Tiêu đề / nhiệm vụ ngắn<input name="title" maxlength="120" required></label><label>Bài học trong lớp đang mở<select name="lessonId"><option value="">Nhiệm vụ do giáo viên tự giao</option>'+pack().lessons.map(l=>'<option value="'+esc(l.lessonId)+'">'+esc(l.title)+'</option>').join('')+'</select></label><label>Hạn nộp<input name="dueAt" type="datetime-local" required></label><label><input name="lockAnswers" type="checkbox" checked> Yêu cầu giữ phần chữa bài đến hạn</label><button type="submit">Giao bài trên máy chủ</button></form><p>Đây là bài luyện/giao nhiệm vụ; không phải hệ thống thi bảo mật. Bài học dạng xem trước vẫn giữ nhãn chưa thẩm định.</p></section>':'')+'<section class="hsw-panel"><h2>Bài đã giao</h2>'+teacherData.assignments.map(a=>'<article class="hsw-assignment"><h3>'+esc(a.title)+'</h3><p>Hạn '+esc(new Date(a.dueAt).toLocaleString('vi-VN'))+'</p></article>').join('')+'</section><section class="hsw-panel"><h2>Bài nộp và chấm nhận xét</h2>'+teacherData.submissions.map(sub=>'<article class="hsw-assignment"><h3>'+esc(teacherData.assignments.find(a=>entryId(a)===String(sub.assignmentId))?.title || 'Bài nộp')+'</h3><p>Hồ sơ '+esc(sub.learnerProfileId)+' · '+esc(sub.status)+' · bản '+Number(sub.answerRevision || 0)+'</p><pre class="hsw-student-answer">'+esc(sub.answer)+'</pre><form data-hsw-grade="'+esc(entryId(sub))+'" data-answer-revision="'+Number(sub.answerRevision || 0)+'"><label>Điểm luyện tập (0–100)<input name="score" type="number" min="0" max="100" step="0.25" value="'+esc(sub.score ?? '')+'" required></label><label>Nhận xét và cách sửa<textarea name="feedback" rows="4" maxlength="3000" required>'+esc(sub.feedback || '')+'</textarea></label><label><input name="redo" type="checkbox"> Yêu cầu sửa và nộp lại</label><button type="submit">Lưu nhận xét trên máy chủ</button></form></article>').join('')+(teacherData.submissions.length?'':'<p>Chưa tải được bài nộp của lớp đang chọn.</p>')+'</section>';
    }
    function saveSession(session){update(p=>{p.examSessions[session.id]=session;p.activeExamId=session.id;},'assessment:save');}
    function mutateExam(action){const p=prefs(),session=p.examSessions[p.activeExamId];if(!session)return;saveSession(A.update(session,action,{now:Date.now(),gradeQuestion:C.gradeQuestion}));}
    function draw(view){
      const status=instance.store.getPersistence?.();if(status?.status==='loading')return header('ĐANG KHÔI PHỤC','Đọc tiến trình đã lưu','Hãy chờ đọc xong trước khi chỉnh sửa để bảo toàn lịch sử.');if(status?.status==='protected')return header('DỮ LIỆU ĐƯỢC BẢO TOÀN','Chưa mở chỉnh sửa',status.error || 'Save chưa tương thích. Bản gốc chưa bị ghi đè.')+'<section class="hsw-panel"><p>Xuất gói phục hồi để giữ dữ liệu gốc trước khi xử lý. Gói này không phải backup đã nhập được vào phiên bản hiện tại.</p><button type="button" data-hsw-recovery>Xuất dữ liệu phục hồi</button></section>';
      const p=state().profile.grade;
      if(loadingGrade&&loadingGrade!==p){controller?.abort();controller=null;loadingGrade=0;}
      if(!content.peekGrade(p)&&loadingGrade!==p&&(!loadError||errorGrade!==p))void ensureGrade(p);
      const prefix=notice()+(status?.error?'<output class="hsw-storage-error" role="status">'+esc(status.error)+'</output>':'');
      if(!content.peekGrade(p)&&['today','subjects','lesson','practice','assessments','library'].includes(view))return prefix+header('NỘI DUNG THEO LỚP',loadError?'Chưa tải được gói lớp '+p:'Đang tải gói lớp '+p,loadError || 'Chỉ tải dữ liệu của lớp đang mở, giữ các bản ghi đã lưu.')+(loadError?'<button type="button" data-hsw-retry>Thử tải lại</button>':'');
      const views={today:home,subjects,lesson,practice,assessments:exam,library,progress,teacher,admin};return views[view]?prefix+'<section class="hsw-surface">'+views[view]()+'</section>':null;
    }
